// FML Lifecycle event handlers
public class MyMod {
    public MyMod() {
        // Subscribe to common setup event
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::onCommonSetup);
        // Subscribe to client setup event
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::onClientSetup);
        // Subscribe to mod construct event
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::onConstructMod);
    }

    private void onConstructMod(FMLConstructModEvent event) {
        // Called when mod is being constructed
        // Good time to register DeferredRegisters
    }

    private void onCommonSetup(FMLCommonSetupEvent event) {
        // Called on both client and server
        // Good time to register recipes, add commands, etc.
        event.enqueueWork(() -> {
            // Must use enqueueWork for threaded operations
            registerRecipes();
            registerCommands();
        });
    }

    private void onClientSetup(FMLClientSetupEvent event) {
        // Client-only setup
        // Register client-side things like keybindings
        event.setToolbarExtension(
            new MyToolbarExtension()
        );
    }
}
